/// Whether a generated typed import exists for this interface/function.
pub fn granted(interface: &str, function: &str) -> bool {
    matches!(
        (interface, function),
        ("soil:records", "get")
            | ("soil:records", "scan")
            | ("soil:records", "query")
            | ("soil:records", "aggregate")
            | ("soil:records", "scan-packed")
            | ("soil:records", "upsert")
            | ("soil:records", "compare-and-swap")
            | ("soil:records", "delete")
            | ("soil:records", "changes")
            | ("soil:records", "apply")
            | ("soil:time", "monotonic-ms")
            | ("soil:time", "wall-clock")
            | ("soil:time", "tick")
    )
}
